// @vitest-environment node
import fs from "node:fs";
import { describe, expect, it } from "vitest";

/**
 * Guards the discovery layer of the static marketing site (airbridge.fyi).
 * The guide pages in website/ are generated by scripts/build-site-pages.mjs;
 * this test fails if metadata, links, structured data or the sitemap drift.
 */
const WEBSITE = "website";
const htmlFiles = fs.readdirSync(WEBSITE).filter((file) => file.endsWith(".html"));
const indexable = htmlFiles.filter((file) => file !== "404.html");

function read(file: string): string {
  return fs.readFileSync(`${WEBSITE}/${file}`, "utf8");
}

function pngSize(path: string): { width: number; height: number } {
  const buffer = fs.readFileSync(path);
  expect(buffer.subarray(1, 4).toString("ascii")).toBe("PNG");
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

describe("Website discovery metadata", () => {
  it("ships every search-intent page, the guides hub and a download page", () => {
    for (const page of [
      "index.html",
      "guides.html",
      "download.html",
      "compare.html",
      "privacy.html",
      "android-to-mac-file-transfer.html",
      "android-to-windows-file-transfer.html",
      "android-to-linux-file-transfer.html",
      "android-airdrop-alternative.html",
      "android-clipboard-sync.html",
      "android-screen-sharing.html",
      "open-source-airdrop-alternative.html",
      "private-file-transfer.html",
    ]) {
      expect(fs.existsSync(`${WEBSITE}/${page}`), page).toBe(true);
    }
  });

  it("gives every indexable page a unique title, description, canonical URL and social preview", () => {
    const titles = new Set<string>();
    const descriptions = new Set<string>();
    for (const file of indexable) {
      const html = read(file);
      const title = html.match(/<title>([^<]+)<\/title>/)?.[1];
      const description = html.match(/name="description" content="([^"]+)"/)?.[1];
      expect(title, `${file} title`).toBeTruthy();
      expect(description, `${file} description`).toBeTruthy();
      expect(title!.length).toBeLessThanOrEqual(90);
      expect(description!.length).toBeGreaterThanOrEqual(60);
      expect(description!.length).toBeLessThanOrEqual(200);
      expect(titles.has(title!), `${file} has a duplicate title`).toBe(false);
      expect(descriptions.has(description!), `${file} has a duplicate description`).toBe(false);
      titles.add(title!);
      descriptions.add(description!);

      const expectedCanonical =
        file === "index.html" ? "https://airbridge.fyi/" : `https://airbridge.fyi/${file}`;
      expect(html).toContain(`<link rel="canonical" href="${expectedCanonical}">`);

      for (const needle of [
        'property="og:title"',
        'property="og:description"',
        'property="og:url"',
        'property="og:image" content="https://airbridge.fyi/og.png"',
        'name="twitter:card" content="summary_large_image"',
        'name="twitter:image" content="https://airbridge.fyi/og.png"',
        '<link rel="icon" href="icon.svg"',
        'href="styles.css"',
        '<html lang="en">',
      ]) {
        expect(html, `${file} missing ${needle}`).toContain(needle);
      }

      expect(html.match(/<h1[\s>]/g)?.length, `${file} h1 count`).toBe(1);
      // Pages are published under a Pages subpath, so assets must stay relative.
      expect(/(?:src|href)="\//.test(html), `${file} uses an absolute asset path`).toBe(false);
      // Every <img> needs alt text for accessibility and image search.
      for (const img of html.match(/<img\b[^>]*>/g) ?? []) {
        expect(img, `${file} image without alt`).toContain("alt=");
      }
    }
  });

  it("keeps JSON-LD structured data valid and supported by visible content", () => {
    for (const file of indexable) {
      const html = read(file);
      const blocks = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)];
      expect(blocks.length, `${file} has structured data`).toBeGreaterThan(0);
      for (const block of blocks) {
        const data = JSON.parse(block[1]!) as Record<string, unknown>;
        expect(data["@context"]).toBe("https://schema.org");
        expect(typeof data["@type"]).toBe("string");
        if (data["@type"] === "FAQPage") {
          const questions = data.mainEntity as Array<{ name: string; acceptedAnswer: { text: string } }>;
          expect(questions.length).toBeGreaterThan(0);
          // A FAQPage is only legitimate when the questions are on the page.
          for (const question of questions) {
            const text = question.name.replace(/\s+/g, " ").slice(0, 40);
            expect(html.replace(/\s+/g, " "), `${file} FAQ answer not visible`).toContain(text);
            expect(html).toContain(question.acceptedAnswer.text.slice(0, 40));
          }
        }
      }
      // No fabricated ratings, reviews or download counts.
      expect(html).not.toMatch(/"aggregateRating"|"reviewCount"|"ratingValue"/);
    }
  });

  it("links resolve locally, anchors exist, and the sitemap lists every indexable page", () => {
    for (const file of htmlFiles) {
      const html = read(file);
      for (const match of html.matchAll(/(?:href|src)="([^"]+)"/g)) {
        const url = match[1]!;
        if (/^(https?:|mailto:|#|\/\/)/.test(url)) continue;
        const [path] = url.split("#");
        if (!path) continue;
        expect(fs.existsSync(`${WEBSITE}/${path}`), `${file} -> ${url}`).toBe(true);
      }
      for (const match of html.matchAll(/href="(?:([a-z0-9-]+\.html))?#([^"]+)"/g)) {
        const target = match[1] ?? file;
        if (!fs.existsSync(`${WEBSITE}/${target}`)) continue;
        expect(read(target), `${file} -> ${target}#${match[2]}`).toContain(`id="${match[2]}"`);
      }
    }

    const sitemap = read("sitemap.xml");
    expect(sitemap).toContain('xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"');
    for (const file of indexable) {
      const loc = file === "index.html" ? "https://airbridge.fyi/" : `https://airbridge.fyi/${file}`;
      expect(sitemap, `sitemap is missing ${loc}`).toContain(`<loc>${loc}</loc>`);
    }
    expect(read("sitemap.xml")).not.toContain("404.html");

    expect(read("robots.txt")).toContain("Sitemap: https://airbridge.fyi/sitemap.xml");
    expect(read("404.html")).toContain('name="robots" content="noindex');
  });

  it("provides a 1200x630 Open Graph image backed by a real screenshot", () => {
    const size = pngSize(`${WEBSITE}/og.png`);
    expect(size).toEqual({ width: 1200, height: 630 });
    for (const screenshot of [
      "screenshots/desktop-file-transfer.jpg",
      "screenshots/desktop-clipboard.png",
      "screenshots/desktop-calls.png",
      "screenshots/phone-transfers.jpg",
    ]) {
      expect(fs.existsSync(`${WEBSITE}/${screenshot}`), screenshot).toBe(true);
    }
  });
});

describe("README discovery layer", () => {
  const readme = fs.readFileSync("README.md", "utf8");

  it("opens with the positioning, download table and supported platforms", () => {
    expect(readme).toContain("Android ↔ Mac, Windows &amp; Linux. Privately.");
    expect(readme).toContain("AirDrop alternative for Android");
    expect(readme).toContain("## Download");
    expect(readme).toContain("## See it running");
    expect(readme).toContain("## Supported platforms");
    expect(readme.indexOf("## Download")).toBeLessThan(readme.indexOf("## Features in detail"));
  });

  it("links only to release artefacts that the release workflow actually publishes", () => {
    const releaseWorkflow = fs.readFileSync(".github/workflows/release.yml", "utf8");
    const linked = [...readme.matchAll(/releases\/latest\/download\/([A-Za-z0-9._-]+)/g)].map(
      (match) => match[1]!,
    );
    expect(linked.length).toBeGreaterThan(0);
    for (const asset of linked) {
      const known =
        releaseWorkflow.includes(asset) ||
        ["AirBridge-macOS-arm64.zip", "AirBridge-macOS-x64.zip", "SHA256SUMS.txt"].includes(asset);
      expect(known, `README links unpublished asset ${asset}`).toBe(true);
    }
  });

  it("keeps security claims honest", () => {
    for (const forbidden of [
      "military-grade",
      "military grade",
      "unhackable",
      "100% secure",
      "zero vulnerabilities",
      "perfect privacy",
    ]) {
      expect(readme.toLowerCase(), `README contains "${forbidden}"`).not.toContain(forbidden);
    }
    expect(readme).toContain("No third-party audit is claimed");
    expect(readme).toContain("CONTRIBUTING.md");
    expect(readme).toContain("CODE_OF_CONDUCT.md");
    expect(readme).toContain("SECURITY.md");
  });
});
